259	Lemma install_spec G x A F : install G x A = Some F <-> substEnv A x G F.
260	Proof.
261	  revert x A F. induction G; intros [] A F; simpl;
262	    try solve [split; [discriminate | intros H; inversion H]];
263	    (destruct (unshift A 0) as [B|] eqn:U;
264	     [apply unshift_correct in U; subst A |
265	      split; [discriminate | intros H; inversion H; subst;
266	      match goal with
267	      | E : unshift (ty_shift ?C 0) 0 = None |- _ =>
268	          pose proof (proj2 (unshift_correct (ty_shift C 0) 0 C) eq_refl);
269	          congruence
270	      end]]);
271	    try (destruct (regular_typ G t) eqn:R; [apply regular_typ_spec in R|]);
272	    try (destruct (regular_typ G B && regular_sub_env G) eqn:R;
273	         [apply andb_true_iff in R as [R S]; apply regular_typ_spec in R;
274	          apply regular_sub_env_spec in S|]);
275	    try rewrite option_map_some; try setoid_rewrite IHG;
276	    split; intros H; try discriminate;
277	    try solve [inversion H; subst; eauto using substEnv];
278	    try solve [destruct H as (? & ? & <-); eauto using substEnv];
279	    inversion H; subst;
280	    match goal with
281	    | U : unshift (ty_shift ?B 0) 0 = Some ?B,
282	      H : ty_shift ?B 0 = ty_shift ?C 0 |- _ =>
283	      apply <- unshift_correct in H; rewrite U in H; injection H as <- 
284	    end;
285	    try solve [eauto];
286	    try (rewrite andb_true_iff, regular_typ_spec, regular_sub_env_spec in R);
287	    try (apply regular_typ_spec in R);
